--- from: Assets/BundleResources/Prefabs/Common/CommonTabToggleLeftExpand.prefab > name: Cell1
---@class CommonTabToggleLeftExpandCell
---@field Env                           	CommonTabToggleLeftExpandCell           
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field ImgNew                        	UnityEngine.RectTransform               
---@field CommonRedPoint                	UnityEngine.RectTransform               
---@field ImgLock                       	UnityEngine.RectTransform               
---@field ImgIcon                       	UnityEngine.RectTransform               
---@field TextName                      	CustomText                              
---@field Unselect                      	UnityEngine.RectTransform               
---@field Select                        	UnityEngine.RectTransform               
---@field Root                          	UnityEngine.RectTransform               
local CommonTabToggleLeftExpandCell = Class('CommonTabToggleLeftExpandCell')

function CommonTabToggleLeftExpandCell:__init()
    self._data = nil
end

function CommonTabToggleLeftExpandCell:__delete()
    self:RemoveTimer()
    self._data = nil
end

function CommonTabToggleLeftExpandCell:Awake()
    if not isNull(self.ImgIcon) then
        local goImage = self.ImgIcon.transform:GetComponent(typeof(ImageAlterable))
        if not goImage then
            goImage = self.ImgIcon.transform:GetComponent(typeof(RawImageAlterable))
        end
        if goImage then
            goImage.IsAutoAlpha = true
        end
    end
end

function CommonTabToggleLeftExpandCell:Start()
    SetButtonAction(self.Root, Bind(self, self.OnClick))
end

function CommonTabToggleLeftExpandCell:Refresh(data, cb)
    if not data then
        return
    end
    self._data = data
    self._cb = cb
    self:RefreshSelect(false)
    self:RefreshCountDown()
    CfUtils.FillText(self.TextName, data.name)
    if checkBool(data.isChild) then 
        self:FillChild()
    else
        self:FillPar()
    end
    
    if data.redPointFun then
        KTool.SetActive(self.CommonRedPoint, data.redPointFun(data))
    else
        KTool.SetActive(self.CommonRedPoint, false)
    end

    if data.newSymbolFun then
        if data.newSymbolFun(data) then
            -- new的优先级高于红点
            CfUtils.SetActive(self.ImgNew, true)
            CfUtils.SetActive(self.CommonRedPoint, false)
        else
            CfUtils.SetActive(self.ImgNew, false)
        end
    else
        CfUtils.SetActive(self.ImgNew, false)
    end
end

function CommonTabToggleLeftExpandCell:RefreshCountDown()
    if not isNull(self.Countdown) then
        if self._data.countDownData  then
            if self._data.countDownData.isCountDown then
                if self._data.countDownData.remainTime > 0 then
                    KTool.SetActive(self.Countdown.gameObject,true)
                    self:StartTimer(self._data.countDownData.remainTime)
                else
                    KTool.SetActive(self.Countdown.gameObject,false)
                end
            elseif self._data.countDownData.isNormalTime then
                KTool.SetActive(self.Countdown.gameObject,true)
                CfUtils.FillText(self.TextTime,CfUtils.GetTimeHMS10(checkNumber(self._data.countDownData.remainTime)))
            else
                KTool.SetActive(self.Countdown.gameObject,false)
            end
        else
            KTool.SetActive(self.Countdown.gameObject,false)
        end
    end
end

function CommonTabToggleLeftExpandCell:StartTimer(remainTime)
    local remainTime = remainTime
    CfUtils.FillText(self.TextTime,CfUtils.GetTimeHMS10(checkNumber(remainTime)))
    self:RemoveTimer()
    if remainTime > 0 then
        self.isTimeOver = false
        self.Timer = CS.Engine.Modules.CDTimerModule.GetInstance():AddCD(1, function(count, id)
            if count > 0 then
                CfUtils.FillText(self.TextTime,CfUtils.GetTimeHMS10(checkNumber(count)))
            else
                CfUtils.FillText(self.TextTime,CfUtils.GetTimeHMS10(checkNumber(0)))
                CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.Timer)
                self.isTimeOver = true
                self.Timer = nil
            end
        end, remainTime + 1, false, true)
    end
end

function CommonTabToggleLeftExpandCell:RemoveTimer()
    if self.Timer then
        CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.Timer)
        self.Timer = nil
    end
end

function CommonTabToggleLeftExpandCell:FillIco(isSelect)
    if self._data.lock then
        CfUtils.SetUISwitchImage(self.ImgIcon, 3)
    else
        CfUtils.SetUISwitchImage(self.ImgIcon, isSelect and 2 or 1)
    end
end

function CommonTabToggleLeftExpandCell:FillPar()
    local imgLock = self.Unselect.transform:Find("ImgLock")
    if not isNull(self._data.lock) then
        if imgLock then
            KTool.SetActive(imgLock.gameObject, self._data.lock)--特殊显示的图片
        end
        CfUtils.SetActive(self.ImgIcon, false)
    else
        KTool.SetActive(imgLock.gameObject, false)--特殊显示的图片
        if not isNull(self._data.bgPath) then
            CfUtils.SetActive(self.ImgIcon, true)
            CfUtils.FillImage(self.ImgIcon, self._data.bgPath)
        else
            CfUtils.SetActive(self.ImgIcon, false)
        end
    end
end

function CommonTabToggleLeftExpandCell:FillChild()
    if not isNull(self._data.IconType) and not isNull(self.TypeIcon) then
        CfUtils.SetUISwitchImage(self.TypeIcon,self._data.IconType)
    end

    if not isNull(self._data.lock) then
        if self.ImgLock then
            KTool.SetActive(self.ImgLock.gameObject, self._data.lock)
        end
    else
        if self.ImgLock then
            KTool.SetActive(self.ImgLock.gameObject, false)
        end
    end
end

function CommonTabToggleLeftExpandCell:RefreshSelect(isTrue)
    KTool.SetActive(self.Select, isTrue)
    CfUtils.SetUISwitchText(self.TextName, isTrue and 2 or 1)
    CfUtils.SetUISwitchImage(self.TextName, isTrue and 2 or 1)

    self:FillIco(isTrue)
end

function CommonTabToggleLeftExpandCell:OnClick()
    if not self._cb then
        return
    end
    self._cb()
end

function CommonTabToggleLeftExpandCell:OnDestroy()
    self:RemoveTimer()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return CommonTabToggleLeftExpandCell